#!/usr/bin/env python3
"""Preserve all scanned normative annex text as OCR context, not new skills."""
from pathlib import Path
import json,hashlib,collections,statistics
ROOT=Path(__file__).resolve().parents[3];SID='sc-cb-em-caderno-6';REV='sc-ept-annex-ocr-context-v1.0.0'
RANGES=[(573,573,'Capa: ANEXOS'),(574,589,'Resolução CNE/CEB nº3 de 21/11/2018'),(591,596,'Lei nº13.415 de 16/02/2017'),(597,616,'Resolução CNE/CP nº2 de 20/12/2019 e BNC-Formação'),(617,619,'Resolução CEB nº2 de 19/04/1999'),(620,626,'Parecer CEE/SC: Curso Normal / Magistério'),(627,631,'Parecer CEE/SC: habilitação em Educação Especial'),(632,636,'Parecer CEE/SC: Magistério Indígena Guarani'),(638,638,'Contracapa e marcas institucionais')]
def run():
 source=next(s for s in json.loads((ROOT/'data/manifests/central-south.json').read_text()) if s['id']==SID);items=[];inventory=[]
 for path in sorted((ROOT/'data/raw/SC/sc-ept-ocr-cache').glob('*.json'),key=lambda p:int(p.stem)):
  raw=json.loads(path.read_text());pn=raw['page'];ww=raw['words'];text=' '.join(w['text'] for w in ww);title=next(t for a,b,t in RANGES if a<=pn<=b);ishistory=pn in [573,638];loc=f'sc-ept-normative-annex:ocr-page:{pn}';rid='ca:'+SID+':'+hashlib.sha256(f'{SID}|{pn}|{loc}|uncoded|occurrence:0'.encode()).hexdigest()[:20]
  if ww:bbox=[min(w['bbox'][0] for w in ww),min(w['bbox'][1] for w in ww),max(w['bbox'][2] for w in ww),max(w['bbox'][3] for w in ww)]
  else:bbox=None
  meta={'source_id':SID,'page':pn,'document':title,'word_count':len(ww),'ocr_reference_path':str(path.relative_to(ROOT)),'ocr_reference_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'confidence_median':statistics.median(w['confidence'] for w in ww) if ww else None,'classification':'cover_metadata' if ishistory else 'normative_annex_context','expected_id':None if ishistory else rid,'ocr_text':text}
  inventory.append(meta)
  if ishistory:continue
  ev={'source_id':SID,'page':pn,'printed_page':str(pn-2),'section':'ANEXOS / '+title,'excerpt':text,'locator':loc,'bbox':bbox,'coordinate_space':raw['coordinate_space'],'method':REV,'ocr_reference_path':meta['ocr_reference_path'],'ocr_reference_sha256':meta['ocr_reference_sha256']}
  items.append({'id':rid,'source_id':SID,'artifact_sha256':source['sha256'],'code':None,'kind':'secao_normativa','text':text,'page':pn,'locator':loc,'positions':[{'stage':'EM','component':'Formação Docente – Curso Normal – Magistério','area':'Anexos normativos da Formação Docente','years':None,'year_label':None,'age_group':None,'period':None,'position_origin':'explicit_source_annex_header'}],'evidence':[ev],'source_context':{'document_part':source['normative_parts'][0],'hierarchy':['Curso Normal em Nível Médio – Magistério','ANEXOS',title],'normative_annex':True,'text_origin':'ocr','confidence_median':meta['confidence_median'],'ocr_reference_path':meta['ocr_reference_path'],'ocr_reference_sha256':meta['ocr_reference_sha256'],'reproduction_of_native_section':'Competências BNC-Formação reproduzidas e estruturadas no corpo nativo, páginas37–46' if 609<=pn<=616 else None,'classification_basis':'Anexo de legislação/parecer; contexto normativo preservado sem classificação como aprendizagem local nova.'},'extraction_method':REV,'extraction_revision':REV,'actor_type':'automated','actor_id':'agent:pr_adapter','technical_validation_status':'ocr_word_cache_checked_not_native_text_or_human_transcription','pedagogical_review_status':'not_reviewed','publication_status':'extracted_candidate'})
 (ROOT/'data/manifests/uncoded/sc-em-ept-annex-items.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n');(ROOT/'docs/evidence/source-audit-sc-ept/annex-ocr-inventory.json').write_text(json.dumps({'source_id':SID,'artifact_sha256':source['sha256'],'expected_ocr_pages':64,'processed_ocr_pages':len(inventory),'blank_native_pages':[590,637],'pages':inventory,'expected_context_ids':[i['expected_id'] for i in inventory if i['expected_id']],'verified_context_ids':[i['id'] for i in items]},ensure_ascii=False,indent=2)+'\n');print('annex normative contexts',len(items),'OCR pages',len(inventory));return items
